// PhotoFrame.js
import React, { useEffect, useRef } from 'react';

const PhotoFrame = ({ photo, userName = 'Participant', location = 'AKESP School' }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!photo || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const img = new Image();
    const objectUrl = URL.createObjectURL(photo);

    const CANVAS_W = 1000;
    const CANVAS_H = 1400;

    const fitText = (text, maxWidth, startSize, weight = '700', family = 'Georgia, serif') => {
      let size = startSize;
      ctx.font = `${weight} ${size}px ${family}`;
      while (size > 16 && ctx.measureText(text).width > maxWidth) {
        size -= 1;
        ctx.font = `${weight} ${size}px ${family}`;
      }
      return size;
    };

    const drawStar = (x, y, r, color = '#d4af37') => {
      ctx.save();
      ctx.fillStyle = color;
      ctx.beginPath();
      for (let i = 0; i < 5; i += 1) {
        const outer = ((18 + i * 72) * Math.PI) / 180;
        const inner = ((54 + i * 72) * Math.PI) / 180;
        ctx.lineTo(Math.cos(outer) * r + x, -Math.sin(outer) * r + y);
        ctx.lineTo(Math.cos(inner) * (r / 2) + x, -Math.sin(inner) * (r / 2) + y);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    };

    img.onload = () => {
      canvas.width = CANVAS_W;
      canvas.height = CANVAS_H;

      ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, CANVAS_W, CANVAS_H);

      const centerX = CANVAS_W / 2;

      ctx.save();
      ctx.fillStyle = '#005a32';
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(290, 0);
      ctx.quadraticCurveTo(80, 70, 0, 290);
      ctx.closePath();
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(CANVAS_W, 0);
      ctx.lineTo(CANVAS_W - 290, 0);
      ctx.quadraticCurveTo(CANVAS_W - 80, 70, CANVAS_W, 290);
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = '#d4af37';
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.moveTo(300, 0);
      ctx.quadraticCurveTo(95, 85, 0, 300);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(CANVAS_W - 300, 0);
      ctx.quadraticCurveTo(CANVAS_W - 95, 85, CANVAS_W, 300);
      ctx.stroke();
      ctx.restore();

      drawStar(centerX, 85, 10);
      drawStar(centerX - 28, 92, 7);
      drawStar(centerX + 28, 92, 7);

      ctx.textAlign = 'center';
      ctx.fillStyle = '#005a32';
      ctx.font = '700 90px Georgia, serif';
      ctx.fillText('100', centerX, 200);

      ctx.fillStyle = '#d4af37';
      ctx.font = '700 26px Arial, sans-serif';
      ctx.fillText('YEARS', centerX, 232);

      ctx.font = '700 17px Arial, sans-serif';
      ctx.fillText('CELEBRATION', centerX, 262);

      const schoolName = location || 'AKESP School';
      const schoolSize = fitText(schoolName, 760, 52, '700');
      ctx.fillStyle = '#005a32';
      ctx.font = `700 ${schoolSize}px Georgia, serif`;
      ctx.fillText(schoolName, centerX, 350);

      ctx.strokeStyle = '#d4af37';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(centerX - 220, 372);
      ctx.lineTo(centerX + 220, 372);
      ctx.stroke();

      const photoY = 620;
      const radius = 195;

      ctx.save();
      ctx.beginPath();
      ctx.arc(centerX, photoY, radius + 16, 0, Math.PI * 2);
      ctx.strokeStyle = '#005a32';
      ctx.lineWidth = 12;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(centerX, photoY, radius + 6, 0, Math.PI * 2);
      ctx.strokeStyle = '#d4af37';
      ctx.lineWidth = 5;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(centerX, photoY, radius, 0, Math.PI * 2);
      ctx.clip();

      const aspect = img.width / img.height;
      let drawW;
      let drawH;
      let drawX;
      let drawY;

      if (aspect > 1) {
        drawH = radius * 2;
        drawW = drawH * aspect;
        drawX = centerX - drawW / 2;
        drawY = photoY - radius;
      } else {
        drawW = radius * 2;
        drawH = drawW / aspect;
        drawX = centerX - radius;
        drawY = photoY - drawH / 2;
      }

      ctx.drawImage(img, drawX, drawY, drawW, drawH);
      ctx.restore();

      ctx.fillStyle = '#d4af37';
      const drawDiamond = (x, y, size = 11) => {
        ctx.beginPath();
        ctx.moveTo(x, y - size);
        ctx.lineTo(x + size, y);
        ctx.lineTo(x, y + size);
        ctx.lineTo(x - size, y);
        ctx.closePath();
        ctx.fill();
      };

      drawDiamond(centerX - radius - 45, photoY, 11);
      drawDiamond(centerX + radius + 45, photoY, 11);

      const bannerY = 900;
      ctx.save();
      ctx.fillStyle = '#005a32';
      ctx.strokeStyle = '#d4af37';
      ctx.lineWidth = 4;

      ctx.beginPath();
      ctx.moveTo(centerX - 260, bannerY - 34);
      ctx.lineTo(centerX + 260, bannerY - 34);
      ctx.lineTo(centerX + 282, bannerY);
      ctx.lineTo(centerX + 260, bannerY + 34);
      ctx.lineTo(centerX - 260, bannerY + 34);
      ctx.lineTo(centerX - 282, bannerY);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#ffffff';
      ctx.font = '700 48px Georgia, serif';
      ctx.fillText('Gift of Reading', centerX, bannerY + 15);
      ctx.restore();

      ctx.fillStyle = '#64748b';
      ctx.font = 'italic 28px Arial, sans-serif';
      ctx.fillText('Presented by', centerX, 995);

      const presentedSize = fitText(schoolName, 680, 36, '700', 'Arial, sans-serif');
      ctx.fillStyle = '#005a32';
      ctx.font = `700 ${presentedSize}px Arial, sans-serif`;
      ctx.fillText(schoolName, centerX, 1040);

      const participantName = userName.trim() || 'Participant';
      const upperName = participantName.toUpperCase();
      const nameSize = fitText(upperName, 760, 64, '700');
      ctx.fillStyle = '#005a32';
      ctx.font = `700 ${nameSize}px Georgia, serif`;
      ctx.fillText(upperName, centerX, 1135);

      ctx.fillStyle = '#d4af37';
      drawDiamond(centerX - (ctx.measureText(upperName).width / 2) - 38, 1120, 8);
      drawDiamond(centerX + (ctx.measureText(upperName).width / 2) + 38, 1120, 8);

      ctx.save();
      ctx.fillStyle = '#005a32';
      ctx.beginPath();
      ctx.moveTo(0, CANVAS_H);
      ctx.lineTo(0, CANVAS_H - 140);
      ctx.bezierCurveTo(230, CANVAS_H - 260, CANVAS_W - 230, CANVAS_H - 260, CANVAS_W, CANVAS_H - 140);
      ctx.lineTo(CANVAS_W, CANVAS_H);
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = '#d4af37';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(0, CANVAS_H - 152);
      ctx.bezierCurveTo(230, CANVAS_H - 272, CANVAS_W - 230, CANVAS_H - 272, CANVAS_W, CANVAS_H - 152);
      ctx.stroke();
      ctx.restore();

      ctx.fillStyle = '#d4af37';
      drawDiamond(220, CANVAS_H - 80, 6);
      drawDiamond(CANVAS_W - 220, CANVAS_H - 80, 6);
      ctx.fillRect(245, CANVAS_H - 82, 46, 4);
      ctx.fillRect(CANVAS_W - 291, CANVAS_H - 82, 46, 4);

      ctx.fillStyle = '#ffffff';
      ctx.font = '700 40px Georgia, serif';
      ctx.fillText('AKESP', centerX, CANVAS_H - 62);
    };

    img.src = objectUrl;

    return () => {
      URL.revokeObjectURL(objectUrl);
    };
  }, [photo, userName, location]);

  const handleDownload = () => {
    if (!canvasRef.current) return;
    const safeName = (userName || 'participant').trim().replace(/\s+/g, '-').toLowerCase();
    const link = document.createElement('a');
    link.download = `reading-frame-${safeName}.png`;
    link.href = canvasRef.current.toDataURL('image/png');
    link.click();
  };

  return (
    <div style={{ textAlign: 'center', marginTop: 24 }}>
      <h3
        style={{
          marginBottom: 14,
          color: '#0f172a',
          fontSize: '1.35rem',
          fontWeight: 800
        }}
      >
        Your Personalized Reading Frame
      </h3>

      <canvas
        ref={canvasRef}
        style={{
          maxWidth: '100%',
          width: 430,
          height: 'auto',
          borderRadius: 16,
          border: '1px solid #e2e8f0',
          boxShadow: '0 18px 36px rgba(2, 6, 23, 0.12)',
          background: '#fff'
        }}
      />

      <div style={{ marginTop: 20 }}>
        <button
          onClick={handleDownload}
          className="auth-btn-next"
          style={{ margin: '0 auto', width: 'auto', padding: '12px 30px' }}
        >
          Download Frame
        </button>
      </div>
    </div>
  );
};

export default PhotoFrame;
